package com.hospital.system.repository; import com.hospital.system.model.Doctor; import java.util.*; import org.springframework.jdbc.core.*; import org.springframework.stereotype.Repository; @Repository public class DoctorRepository { private final JdbcTemplate db; public DoctorRepository(JdbcTemplate db){this.db=db;} private final RowMapper<Doctor> m=(r,n)->{Doctor d=new Doctor();d.doctorId=r.getLong("doctor_id");d.fullName=r.getString("full_name");d.specialization=r.getString("specialization");d.departmentId=r.getLong("department_id");d.departmentName=r.getString("department_name");d.phone=r.getString("phone");d.consultationFee=r.getBigDecimal("consultation_fee");d.availableFrom=r.getObject("available_from",java.time.LocalTime.class);d.availableTo=r.getObject("available_to",java.time.LocalTime.class);return d;}; public List<Doctor> all(String q){String x=q==null?"":q;return db.query("SELECT d.*,dp.department_name FROM doctor d JOIN department dp ON dp.department_id=d.department_id WHERE d.full_name LIKE ? OR d.specialization LIKE ? ORDER BY d.doctor_id DESC",m,"%"+x+"%","%"+x+"%");} public Optional<Doctor> one(Long id){return db.query("SELECT d.*,dp.department_name FROM doctor d JOIN department dp ON dp.department_id=d.department_id WHERE d.doctor_id=?",m,id).stream().findFirst();} public int add(Doctor d){return db.update("INSERT INTO doctor(full_name,specialization,department_id,phone,consultation_fee,available_from,available_to) VALUES(?,?,?,?,?,?,?)",d.fullName,d.specialization,d.departmentId,d.phone,d.consultationFee,d.availableFrom,d.availableTo);} public int update(Long id,Doctor d){return db.update("UPDATE doctor SET full_name=?,specialization=?,department_id=?,phone=?,consultation_fee=?,available_from=?,available_to=? WHERE doctor_id=?",d.fullName,d.specialization,d.departmentId,d.phone,d.consultationFee,d.availableFrom,d.availableTo,id);} public int delete(Long id){return db.update("DELETE FROM doctor WHERE doctor_id=?",id);} }
